//! Tokenizer encodings must match the reference HF `tokenizers` outputs in tests/fixtures
//! (generated by tests/fixtures/make_fixtures.py).

use std::path::PathBuf;

use sky_gguf::{Gguf, GgufWriter, OwnedValue};
use sky_infer::json::Json;
use sky_infer::tokenizer::{token_type, Tokenizer};

mod models;

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn oscar_tokenizer_path() -> PathBuf {
    models::oscar_dir().join("tokenizer/tokenizer.json")
}

fn cases(set: &str) -> Vec<(String, Vec<u32>)> {
    let text = std::fs::read_to_string(fixtures().join("tokenizer_cases.json")).unwrap();
    let j = Json::parse(&text).unwrap();
    let Some(arr) = j.get(set).and_then(|v| v.as_array()) else {
        return Vec::new();
    };
    arr.iter()
        .map(|c| {
            let t = c.get("text").unwrap().as_str().unwrap().to_string();
            let ids = c
                .get("ids")
                .unwrap()
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_u64().unwrap() as u32)
                .collect();
            (t, ids)
        })
        .collect()
}

fn check(tok: &Tokenizer, set: &str) {
    let cases = cases(set);
    assert!(!cases.is_empty(), "no fixtures for {set}");
    let mut failures = Vec::new();
    for (text, ids) in &cases {
        let got = tok.encode(text);
        if &got != ids {
            failures.push(format!("{text:?}\n  want {ids:?}\n  got  {got:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{set}: {} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn small_tokenizer_matches_hf() {
    let json = std::fs::read_to_string(fixtures().join("small_tokenizer.json")).unwrap();
    let tok = Tokenizer::from_tokenizer_json(&json).unwrap();
    let sp = tok.special();
    assert_eq!(
        (sp.pad, sp.unk, sp.cls, sp.sep, sp.mask),
        (Some(0), Some(1), Some(2), Some(3), Some(4))
    );
    check(&tok, "small");
}

#[test]
fn string_merges_form_is_equivalent() {
    let a = Tokenizer::from_tokenizer_json(
        &std::fs::read_to_string(fixtures().join("small_tokenizer.json")).unwrap(),
    )
    .unwrap();
    let b = Tokenizer::from_tokenizer_json(
        &std::fs::read_to_string(fixtures().join("small_tokenizer_strmerges.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(a.merges(), b.merges());
    check(&b, "small");
}

#[test]
fn oscar_tokenizer_matches_hf() {
    let path = oscar_tokenizer_path();
    let tok = Tokenizer::from_tokenizer_json(&std::fs::read_to_string(path).unwrap()).unwrap();
    assert!(tok.is_nfc());
    let sp = tok.special();
    assert_eq!(
        (sp.unk, sp.cls, sp.sep, sp.pad, sp.mask),
        (
            Some(50280),
            Some(50281),
            Some(50282),
            Some(50283),
            Some(50284)
        )
    );
    check(&tok, "oscar");
}

/// Write the tokenizer to GGUF the way `sky-convert` does and check it encodes identically.
fn through_gguf(tok: &Tokenizer) -> Tokenizer {
    let n = tok.vocab_size();
    let mut tokens = vec![String::new(); n];
    let mut types = vec![token_type::UNUSED; n];
    for (s, &id) in tok.vocab() {
        tokens[id as usize] = s.clone();
        types[id as usize] = token_type::NORMAL;
    }
    let mut lstrip = Vec::new();
    for a in tok.added_tokens() {
        tokens[a.id as usize] = a.content.clone();
        types[a.id as usize] = if a.special {
            token_type::CONTROL
        } else {
            token_type::USER_DEFINED
        };
        if a.lstrip {
            lstrip.push(OwnedValue::I32(a.id as i32));
        }
    }
    for (i, t) in tokens.iter_mut().enumerate() {
        if t.is_empty() {
            *t = format!("[PAD{i}]");
        }
    }
    let merges: Vec<String> = tok
        .merges()
        .into_iter()
        .map(|(a, b)| format!("{a} {b}"))
        .collect();
    let mut w = GgufWriter::new();
    w.add_kv("tokenizer.ggml.model", "gpt2")
        .add_kv("tokenizer.ggml.tokens", OwnedValue::strings(&tokens))
        .add_kv(
            "tokenizer.ggml.token_type",
            OwnedValue::Array(types.into_iter().map(OwnedValue::I32).collect()),
        )
        .add_kv("tokenizer.ggml.merges", OwnedValue::strings(&merges))
        .add_kv("skycmd.tokenizer.lstrip", OwnedValue::Array(lstrip));
    if tok.is_nfc() {
        w.add_kv("skycmd.tokenizer.normalizer", "nfc");
    }
    if let Some(m) = tok.special().mask {
        w.add_kv("tokenizer.ggml.mask_token_id", m);
    }
    let bytes = w.to_bytes().unwrap();
    Tokenizer::from_gguf(&Gguf::parse(&bytes).unwrap()).unwrap()
}

#[test]
fn gguf_round_trip_small() {
    let tok = Tokenizer::from_tokenizer_json(
        &std::fs::read_to_string(fixtures().join("small_tokenizer.json")).unwrap(),
    )
    .unwrap();
    check(&through_gguf(&tok), "small");
}

#[test]
fn gguf_round_trip_oscar() {
    let path = oscar_tokenizer_path();
    let tok = Tokenizer::from_tokenizer_json(&std::fs::read_to_string(path).unwrap()).unwrap();
    let g = through_gguf(&tok);
    assert_eq!(g.special().mask, tok.special().mask);
    check(&g, "oscar");
}

#[test]
fn decode_round_trip() {
    let tok = Tokenizer::from_tokenizer_json(
        &std::fs::read_to_string(fixtures().join("small_tokenizer.json")).unwrap(),
    )
    .unwrap();
    for (text, _) in cases("small") {
        assert_eq!(tok.decode(&tok.encode(&text), false), text);
    }
}
